with open("region.fasta") as f:
    f.readline()
    s = "".join(l.strip() for l in f)

core = "AGTTCCCCGCGCCAGCGGGGATAAACCG"

def fuzzy_hits(seq, pat, maxmm):
    hits=[]
    L=len(pat)
    for i in range(len(seq)-L+1):
        seg=seq[i:i+L]
        mm=sum(1 for a,b in zip(seg,pat) if a!=b)
        if mm<=maxmm:
            hits.append((i+1, mm, seg))
    return hits

for mm in (0,1,2,3):
    hits = fuzzy_hits(s, core, mm)
    print(f"\n=== motif with <= {mm} mismatches: {len(hits)} hits ===")
    for pos, m, seg in hits:
        print(f"  1-based {pos}-{pos+27}  mismatches={m}  {seg}")
